INSERT INTO hostels (id, name, block_code, location, description, facilities, warden_name, warden_phone, gender_policy, is_active) VALUES
(1,'Narra Hall','BLK-A','North Campus, near the Main Library','A modern four-storey ladies\' residence with ensuite bathrooms, a dedicated study lounge on every floor and card-access security.','Wi-Fi, Air Conditioning, Study Lounge, 24/7 Security, Hot Water, Laundry Room','Mrs. Teresita Abella','09182220001','female',1),
(2,'Acacia Hall','BLK-B','North Campus, beside the Sports Complex','Gentlemen\'s block with direct access to the university gym, covered parking for motorcycles and CCTV-monitored corridors.','Wi-Fi, Air Conditioning, Gym Access, 24/7 Security, CCTV, Parking','Mr. Ernesto Cabral','09182220002','male',1),
(3,'Molave Residence','BLK-C','South Campus, behind the Engineering Building','Mixed-gender residence (separate wings) popular with engineering students; steps away from the laboratories and the 24-hour canteen.','Wi-Fi, Study Lounge, Canteen, Laundry Room, Power Backup, Hot Water','Ms. Divina Orlina','09182220003','mixed',1),
(4,'Ipil Court','BLK-D','South Campus, near the Medical Clinic','Postgraduate and senior-year court-style accommodation with shared kitchenettes and quiet-hours enforcement after 10 PM.','Wi-Fi, Air Conditioning, Kitchenette, 24/7 Security, Power Backup, Study Lounge','Mr. Alfredo Sinco','09182220004','mixed',1);
INSERT INTO room_types (id, name, capacity, price, facilities, description) VALUES
(1,'Single Deluxe',1,18500.00,'Air Conditioning, Private Bathroom, Study Desk, Wardrobe, Wi-Fi','Private room with an ensuite bathroom, a full-size desk and ample storage — ideal for postgraduate students.'),
(2,'Twin Sharing',2,12800.00,'Air Conditioning, Shared Bathroom, Study Desk, Wardrobe, Wi-Fi','Two single beds with individual study desks and a shared ensuite bathroom.'),
(3,'Triple Room',3,9600.00,'Ceiling Fan, Shared Bathroom, Study Desk, Wardrobe, Wi-Fi','Three beds with personal lockers, a shared bathroom and a common study table.'),
(4,'Quad Dormitory',4,7200.00,'Ceiling Fan, Shared Bathroom, Locker, Wi-Fi','Budget-friendly four-bed dormitory with individual lockers and a shared bathroom.');
