-- Sync room occupancy counters and status flags
UPDATE rooms SET occupied = 1 WHERE id = 9;
UPDATE rooms SET occupied = 1 WHERE id = 1;
UPDATE rooms SET occupied = 1 WHERE id = 31;
UPDATE rooms SET occupied = 1 WHERE id = 61;
UPDATE rooms r JOIN room_types rt ON rt.id = r.room_type_id SET r.status = IF(r.occupied >= rt.capacity,'full','available');
-- Two spare rooms go under maintenance so the vacancy report has variety
UPDATE rooms SET status = 'maintenance' WHERE occupied = 0 ORDER BY id DESC LIMIT 2;

